//#CTL2
// Epoch-millisecond subtraction measures elapsed UTC time, not calendar hours.
// Validate the full duration before truncating each qualifying duration to hours.
// Decimal rounding is half up; groups with no eligible incidents retain null.
function void initGroup(LegalIncidentStateRecord acc) {
    acc.accumulated_hours = 0L;
    acc.eligible_count = 0L;
    acc.average_hours = null;
}

function boolean updateGroup(LegalIncidentStateRecord acc) {
    if (!isnull($in.0.received_at) && !isnull($in.0.resolved_at)) {
        long elapsedMillis = date2long($in.0.resolved_at) - date2long($in.0.received_at);
        if (elapsedMillis >= 0L && elapsedMillis <= 259200000L) {
            long wholeHours = elapsedMillis / 3600000L;
            acc.accumulated_hours = acc.accumulated_hours + wholeHours;
            acc.eligible_count = acc.eligible_count + 1L;
        }
    }
    return false;
}

function boolean finishGroup(LegalIncidentStateRecord acc) {
    if (acc.eligible_count > 0L) {
        decimal totalHours = acc.accumulated_hours;
        acc.average_hours = round(totalHours / acc.eligible_count, 2);
