            $out.0.queue_rank = 1;
        } else if (offset < 30) {
            $out.0.delay_class = "moderate";
            $out.0.queue_rank = 2;
        } else if (offset < 60) {
            $out.0.delay_class = "major";
            $out.0.queue_rank = 3;
        } else {
            $out.0.delay_class = "critical";
            $out.0.queue_rank = 4;
        }
    }

    $out.0.supervisor_alert = offset < -15 || offset >= 60;
    if (offset < 0) {
        $out.0.dispatch_action = "reschedule";
    } else if (offset >= 60) {
        $out.0.dispatch_action = "escalate";
    } else {
        $out.0.dispatch_action = "proceed";
