//#CTL2

// Count every submission, but preserve the previous known amount across nulls.
// Movement stays null until a second known amount occurs. Only emitted groups
// advance the run-wide sequence; single-source groups are suppressed.
long emittedSequence = 0;

function void initGroup(CashDeclarationState acc) {
    acc.submissions_seen = 0;
    acc.prior_known_usd = null;
    acc.cumulative_movement_usd = null;
}

function boolean updateGroup(CashDeclarationState acc) {
    acc.submissions_seen = acc.submissions_seen + 1;
    if (!isnull($in.0.declared_usd)) {
        if (!isnull(acc.prior_known_usd)) {
            if (isnull(acc.cumulative_movement_usd)) {
                acc.cumulative_movement_usd = 0d;
            }
            acc.cumulative_movement_usd = acc.cumulative_movement_usd
                + abs($in.0.declared_usd - acc.prior_known_usd);
        }
        acc.prior_known_usd = $in.0.declared_usd;
    }
    return false;
}

function boolean finishGroup(CashDeclarationState acc) {
    if (acc.submissions_seen < 2) {
        return false;
    }
    emittedSequence = emittedSequence + 1;
    return true;
}

function integer updateTransform(integer counter, CashDeclarationState acc) {
    return SKIP;
}

function integer transform(integer counter, CashDeclarationState acc) {
    if (counter != 0) return SKIP;
    if (acc.submissions_seen < 2) return SKIP;
    $out.0.casereference = $in.0.case_reference;
    $out.0.submission_total = acc.submissions_seen;
    $out.0.revision_movement_usd = acc.cumulative_movement_usd;
    $out.0.audit_sequence = emittedSequence;
    $out.0.movement_available = !isnull(acc.cumulative_movement_usd);
    return ALL;
}
