    if (issues > 0) $out.0.handling_lane = "INSPECTION";
    else if ($in.0.requested_units > $in.0.available_units) $out.0.handling_lane = "REPLENISH";
    else $out.0.handling_lane = "DISPATCH";

    if (isnull($in.0.available_units)) $out.0.stock_class = "UNKNOWN";
    else if ($in.0.available_units <= 0) $out.0.stock_class = "EMPTY";
    else if ($in.0.available_units >= 100) $out.0.stock_class = "BULK";
    else $out.0.stock_class = "SMALL";

    if (isnull($in.0.available_units) || isnull($in.0.requested_units)) $out.0.coverage_class = "UNKNOWN";
    else if ($in.0.available_units < 0 || $in.0.requested_units <= 0) $out.0.coverage_class = "INVALID";
    else if ($in.0.requested_units > $in.0.available_units) $out.0.coverage_class = "SHORT";
    else $out.0.coverage_class = "COVERED";
    return ALL;
}
