//#CTL2
integer rule;
long elapsed;
long credited;

function integer count() {
    if ($in.0.duty_end == null) {
        rule = 1;
        return 1;
    }
    elapsed = (date2long($in.0.duty_end) - date2long($in.0.duty_start)) / 60000L;
    credited = elapsed;
    if ($in.0.meal_deduction != null) credited = credited - $in.0.meal_deduction;
    if ($in.0.duty_code == "VOID") {
        rule = 2;
        return 0;
    }
    if (elapsed < 0L) {
        rule = 3;
        return 1;
    }
    if (!$in.0.supervisor_cleared || $in.0.duty_code == null) {
        rule = 4;
        return 1;
    }
    if (startsWith($in.0.duty_code, "COURSE-")) {
        rule = 5;
        return 1;
    }
    if ($in.0.duty_code == "CATERING" && elapsed >= 40L) {
        rule = 6;
        return 3;
    }
    if (credited >= 450L) {
        rule = 7;
        return 2;
    }
    if ($in.0.spot_check && credited > 0L) {
        rule = 8;
        return 2;
    }
    rule = 9;
    return 1;
}

function integer transform(integer idx) {
    string code = "RESTAURANT_DUTY";
    long minutes = 0L;
    long startOffset = 0L;
    long endOffset = 0L;
    boolean paid = false;
    if (rule == 1) {
        code = "UNFINISHED";
