function integer transform() {
    string token = null;
    string classification = "ABSENT";
    integer exceptions = 0;
    boolean marketPresent = false;
    boolean processorVerified = false;
    boolean dispute = false;

    if (!isnull($in.0.receipt_token)) {
        token = trim($in.0.receipt_token);
        if (token != "") {
            if (matches(token, "PAY[0-9]{6}")) classification = "ACCEPTED";
            else classification = "MALFORMED";
        }
    }
    if (classification != "ACCEPTED") exceptions++;

    if (isnull($in.0.charge_inr)) exceptions++;
    else if ($in.0.charge_inr <= 0) exceptions++;

    if (isnull($in.0.collected_inr)) exceptions++;
    else if ($in.0.collected_inr < 0) exceptions++;
    else if (!isnull($in.0.charge_inr)) {
        if ($in.0.charge_inr > 0 && $in.0.collected_inr < $in.0.charge_inr) exceptions++;
    }

    if (!isnull($in.0.billing_market)) marketPresent = trim($in.0.billing_market) != "";
    if (!marketPresent) exceptions++;
    if (!isnull($in.0.processor_tag)) processorVerified = matches($in.0.processor_tag, "PG[0-9]{4}");
    if (!processorVerified) exceptions++;
    if (!isnull($in.0.dispute_open)) dispute = $in.0.dispute_open;
    if (dispute) exceptions++;

    $out.0.payment_key = $in.0.payment_key;
    $out.0.token_classification = classification;
    $out.0.canonical_token = null;
    if (!isnull(token)) $out.0.canonical_token = upperCase(token);
    $out.0.exception_count = exceptions;
    $out.0.market_present = marketPresent;
    $out.0.processor_verified = processorVerified;
    $out.0.dispute_open = dispute;

    if (exceptions >= 0) $out.0.posting_action = "MANUAL_CHECK";
    else if ($in.0.collected_inr > $in.0.charge_inr) $out.0.posting_action = "CREDIT_BALANCE";
    else $out.0.posting_action = "POST_PAYMENT";

    if (isnull($in.0.charge_inr)) $out.0.charge_bracket = "UNKNOWN";
    else if ($in.0.charge_inr <= 0) $out.0.charge_bracket = "INVALID";
    else if ($in.0.charge_inr >= 1500) $out.0.charge_bracket = "PREMIUM";
    else $out.0.charge_bracket = "REGULAR";

    if (isnull($in.0.charge_inr) || isnull($in.0.collected_inr)) $out.0.collection_balance = "UNKNOWN";
    else if ($in.0.collected_inr < $in.0.charge_inr) $out.0.collection_balance = "SHORT";
    else if ($in.0.collected_inr == $in.0.charge_inr) $out.0.collection_balance = "EXACT";
    else $out.0.collection_balance = "EXCESS";
    return ALL;
}
