//#CTL2

function integer count() {
    if ($in.0.settlement_kind == "WITHDRAWN") return 0;
    if ($in.0.delivered_kg < 0) return 1;
    if (isnull($in.0.agreement_code)) return 1;
    if ($in.0.settlement_kind == "RETURN") return 1;
    if ($in.0.settlement_kind == "POOL" && $in.0.organic_certified && $in.0.delivered_kg > 1000) return 3;
    if ($in.0.delivered_kg == 0) return 0;
    if ($in.0.settlement_kind == "POOL") return 2;
    return 1;
}

function integer transform(integer idx) {
    $out.0.delivery_reference = $in.0.delivery_number;

    if ($in.0.delivered_kg < 0) {
        $out.0.settlement_entry = "WEIGHT_ERROR";
        $out.0.euro_amount = 0;
    } else if (isnull($in.0.agreement_code)) {
        $out.0.settlement_entry = "AGREEMENT_HOLD";
        $out.0.euro_amount = 0;
    } else if ($in.0.settlement_kind == "RETURN") {
        $out.0.settlement_entry = "RETURN_DEBIT";
        $out.0.euro_amount = -$in.0.price_per_kg * $in.0.delivered_kg;
    } else if ($in.0.settlement_kind == "POOL") {
        if (idx == 0) {
            $out.0.settlement_entry = "GROWER";
            $out.0.euro_amount = $in.0.price_per_kg * $in.0.delivered_kg * 90 / 100;
        } else if (idx == 1) {
            $out.0.settlement_entry = "COOPERATIVE";
            $out.0.euro_amount = $in.0.price_per_kg * $in.0.delivered_kg * 10 / 100;
        } else {
            $out.0.settlement_entry = "CERTIFICATION_LOG";
            $out.0.euro_amount = 0;
        }
    } else {
        $out.0.settlement_entry = "DIRECT_SETTLEMENT";
        $out.0.euro_amount = $in.0.price_per_kg * $in.0.delivered_kg;
    }
    return OK;
}
