    if (isnull($in.0.transfer_aed)) {
        tier = "UNAVAILABLE";
    } else if ($in.0.transfer_aed <= 0) {
        tier = "INVALID";
    } else if ($in.0.transfer_aed >= 100000) {
        tier = "LARGE";
    } else {
        tier = "ROUTINE";
    }

    string capacity;
    if (isnull($in.0.channel_ceiling_aed)) {
        capacity = "UNAVAILABLE";
    } else if (!ceilingPositive) {
        capacity = "INVALID";
    } else if (!transferPositive) {
        capacity = "UNASSESSED";
    } else if (exceeded) {
        capacity = "EXCEEDED";
    } else {
        capacity = "WITHIN";
    }

    $out.0.message_key = $in.0.message_key;
    $out.0.reference_state = referenceState;
    $out.0.canonical_reference = canonical;
