//#CTL2

function integer selectedRule() {
    boolean inspect = $in.0.inspection_required == true;
    boolean sameJob = ($in.0.previous_job == null && $in.0.proposed_job == null)
        || ($in.0.previous_job != null && $in.0.proposed_job != null
            && $in.0.previous_job == $in.0.proposed_job);
    boolean sameCosts = $in.0.previous_cost == $in.0.proposed_cost;

    if ($in.0.maintenance_event == "DUPLICATE") return 1;
    if (($in.0.maintenance_event == "COMMISSION" || $in.0.maintenance_event == "REPLACE")
        && ($in.0.proposed_job == null || $in.0.proposed_cost <= 0)) return 2;
    if ($in.0.maintenance_event == "DEFER" && !inspect) return 3;
    if ($in.0.maintenance_event == "SERVICE" && $in.0.warranty_until != null
        && $in.0.recorded_at < $in.0.warranty_until) return 4;
    if (sameJob && sameCosts && inspect) return 5;
    if (sameJob && sameCosts) return 6;
