function integer transform() {
    $out.0.tender_ref = $in.0.tender_ref;
    string text = null;
    if (!isnull($in.0.cover_start_text)) text = trim($in.0.cover_start_text);
    $out.0.cover_start_key = null;
    $out.0.cover_start_check = "MISSING";
    if (!isnull(text) && text != "") {
        $out.0.cover_start_check = "INVALID";
        if (length(text) == 10 && isDate(text, "yyyy-MM-dd", "en.US", "UTC", true)) {
            date parsed = str2date(text, "yyyy-MM-dd", "en.US", "UTC", true);
            if (date2str(parsed, "yyyy-MM-dd", "en.US", "UTC") == text) {
                $out.0.cover_start_check = "VALID";
                $out.0.cover_start_key = date2str(parsed, "yyyyMMdd", "en.US", "UTC");
            }
        }
    }

    string broker = null;
    if (!isnull($in.0.broker_reference)) broker = upperCase(trim($in.0.broker_reference));
    $out.0.broker_key = broker;
    if (isnull(broker) || broker == "") {
        $out.0.broker_check = "MISSING";
    } else if (length(broker) > 3 && substring(broker, 0, 3) == "AE-") {
        $out.0.broker_check = "LOCAL";
    } else {
        $out.0.broker_check = "FOREIGN";
    }

    if (isnull($in.0.annual_premium_aed)) $out.0.premium_check = "MISSING";
    else if ($in.0.annual_premium_aed <= 0) $out.0.premium_check = "INVALID";
    else if ($in.0.annual_premium_aed >= 100000) $out.0.premium_check = "REVIEW";
    else $out.0.premium_check = "OK";

    if (isnull($in.0.offers_received)) $out.0.bid_band = "MISSING";
    else if ($in.0.offers_received <= 0) $out.0.bid_band = "INVALID";
    else if ($in.0.offers_received >= 3) $out.0.bid_band = "COMPETITIVE";
    else $out.0.bid_band = "LIMITED";

    boolean signed = false;
    if (!isnull($in.0.compliance_signed)) signed = $in.0.compliance_signed;
    $out.0.compliance_signed = signed;
    integer exceptions = 0;
    if ($out.0.cover_start_check != "VALID") exceptions++;
    if ($out.0.broker_check != "LOCAL") exceptions++;
    if ($out.0.premium_check != "OK") exceptions++;
    if ($out.0.bid_band == "MISSING" || $out.0.bid_band == "INVALID") exceptions++;
    if (!isnull($in.0.annual_premium_aed)) {
        if ($in.0.annual_premium_aed > 1000 && !signed) exceptions++;
    }
    $out.0.procurement_exceptions = exceptions;
    if (exceptions > 0) $out.0.routing_lane = "HOLD";
    else if ($out.0.bid_band == "LIMITED" || !signed) $out.0.routing_lane = "NEGOTIATE";
    else $out.0.routing_lane = "AWARD_REVIEW";
    return ALL;
}
