    acc.submissions_seen = acc.submissions_seen + 1L;
    if (!isnull($in.0.declared_proceeds)) {
        if (!isnull(acc.prior_proceeds)) {
            if (isnull(acc.upward_revision_total)) {
                acc.upward_revision_total = 0d;
            }
            if ($in.0.declared_proceeds > acc.prior_proceeds) {
                acc.upward_revision_total = acc.upward_revision_total
                    + ($in.0.declared_proceeds - acc.prior_proceeds);
            }
        }
        acc.prior_proceeds = $in.0.declared_proceeds;
    }
    return false;
}

function boolean finishGroup(RentalReturnState acc) {
    return true;
}

function integer updateTransform(integer counter, RentalReturnState acc) {
    return SKIP;
}

function integer transform(integer counter, RentalReturnState acc) {
    if (counter != 0) return SKIP;
    if (acc.submissions_seen < 2L) return SKIP;
    emittedSummaries = emittedSummaries + 1L;
    $out.0.property_ref = $in.0.property_ref;
    $out.0.submission_count = acc.submissions_seen;
    $out.0.additional_proceeds = acc.upward_revision_total;
    $out.0.summary_sequence = emittedSummaries;
    $out.0.has_comparable_returns = !isnull(acc.upward_revision_total);
    return ALL;
}
