        $out.0.arrival_check = "MISSING";
    } else if (matches(arrival, "[0-9]{4}-[0-9]{2}-[0-9]{2}")) {
        if (isDate(arrival, "yyyy-MM-dd", "en.US", "UTC", true)) {
            date parsed = str2date(arrival, "yyyy-MM-dd", "en.US", "UTC", true);
            if (date2str(parsed, "yyyy-MM-dd", "en.US", "UTC") == arrival) {
                $out.0.arrival_check = "VALID";
