        $out.0.occupancy_check = "MISSING";
    } else if (guests <= 0) {
        $out.0.occupancy_check = "INVALID";
    } else {
        $out.0.occupancy_check = "OK";
        if (!isnull(rooms)) {
            if (rooms > 0 && guests > rooms * 4L) {
                $out.0.occupancy_check = "OVER_CAPACITY";
            }
        }
    }

    if (isnull(rooms)) {
        $out.0.room_tier = "MISSING";
    } else if (rooms <= 0) {
        $out.0.room_tier = "INVALID";
    } else if (rooms > 8) {
        $out.0.room_tier = "GROUP";
    } else if (rooms == 1) {
        $out.0.room_tier = "SOLO";
    } else {
        $out.0.room_tier = "STANDARD";
    }

    if ($out.0.arrival_check != "VALID") problems++;
    if ($out.0.property_check != "OK") problems++;
    if ($out.0.occupancy_check != "OK") problems++;
    if ($out.0.room_tier == "MISSING" || $out.0.room_tier == "INVALID") problems++;
    if (!isnull(rooms)) {
        if (rooms > 3 && !guaranteed) problems++;
    }
    $out.0.problem_count = problems;

    if (problems > 0) {
        $out.0.routing_lane = "REVIEW";
    } else if ($out.0.room_tier == "GROUP") {
        $out.0.routing_lane = "GROUP_DESK";
    } else {
        $out.0.routing_lane = "CONFIRMED";
    }
    return SKIP;
}
