//#CTL2
function integer transform() {
    string ref = null;
    boolean exempt = false;
    boolean stopPresent = false;
    boolean verified = false;
    boolean badObserved = false;
    boolean badValidations = false;
    integer findings = 0;

    $out.0.audit_key = $in.0.audit_key;
    if ($in.0.inspection_ref != null) {
        ref = trim($in.0.inspection_ref);
    }
    $out.0.canonical_ref = null;
