        if ($in.0.observed_riders != null) {
            if ($in.0.recorded_validations > $in.0.observed_riders) {
                badValidations = true;
            }
        }
    }

    if ($in.0.observed_riders == null || $in.0.recorded_validations == null) {
        $out.0.reconciliation_class = "UNKNOWN";
    } else if ($in.0.observed_riders < 0 || $in.0.recorded_validations < 0 || $in.0.recorded_validations > $in.0.observed_riders) {
        $out.0.reconciliation_class = "INVALID";
    } else if ($in.0.observed_riders > $in.0.recorded_validations) {
        $out.0.reconciliation_class = "GAP";
    } else {
        $out.0.reconciliation_class = "BALANCED";
    }

    if ($out.0.ref_assessment != "ACCEPTED") { findings++; }
    if (badObserved) { findings++; }
    if (badValidations) { findings++; }
    if (!stopPresent) { findings++; }
    if (!verified && !exempt) { findings++; }
