        $out.0.audit_action = "CORRECT";
    } else if (!exempt && $in.0.observed_riders > $in.0.recorded_validations) {
        $out.0.audit_action = "TARGETED";
    } else {
        $out.0.audit_action = "ROUTINE";
    }
    return SKIP;
}
