//#CTL2
function integer transform() {
    string card = "";
    if (!isnull($in.0.card_reference)) card = trim($in.0.card_reference);
    string classification;
    if (card == "") classification = "MISSING";
    else if (matches(card, "EL[0-9]{8}")) classification = "VALID";
    else classification = "INVALID";

    string airport = "";
    if (!isnull($in.0.base_airport)) airport = upperCase(trim($in.0.base_airport));
    boolean supported = airport == "WAW" || airport == "KRK" || airport == "OTP" || airport == "SOF";
    boolean verified = false;
    if (!isnull($in.0.service_agent)) verified = matches($in.0.service_agent, "LOY[0-9]{4}");
    boolean blocked = false;
    if (!isnull($in.0.account_frozen)) blocked = $in.0.account_frozen;

    long accrued = $in.0.accrued_miles;
    long requested = $in.0.requested_miles;
    integer issues = 0;
    if (classification != "VALID") issues++;
    if (isnull(accrued)) issues++;
    else if (accrued < 0) issues++;
    if (isnull(requested)) issues++;
    else if (requested <= 0) issues++;
    if (!isnull(accrued) && !isnull(requested)) {
        if (requested > accrued) issues++;
    }
    if (!supported) issues++;
    if (!verified) issues++;
    if (blocked) issues++;

    string balanceTier;
    if (isnull(accrued)) balanceTier = "UNKNOWN";
    else if (accrued < 0) balanceTier = "INVALID";
    else if (accrued >= 100000) balanceTier = "PREMIUM";
    else balanceTier = "REGULAR";

    string requestTier;
    if (isnull(requested)) requestTier = "UNKNOWN";
    else if (requested <= 0) requestTier = "INVALID";
    else if (requested >= 25000) requestTier = "LARGE";
    else requestTier = "SMALL";

    string lane = "REVIEW";
    if (issues == 0) {
        // Here 0 < requested <= accrued. This exact half comparison
        // avoids both fractional truncation and long multiplication overflow.
        if (requested <= accrued - requested) lane = "INSTANT";
        else lane = "APPROVAL";
    }

    $out.0.member_key = $in.0.member_key;
    $out.0.card_classification = classification;
    $out.0.canonical_card = upperCase(card);
    $out.0.issue_count = issues;
    $out.0.processing_lane = lane;
    $out.0.balance_tier = balanceTier;
    $out.0.request_tier = requestTier;
    $out.0.base_supported = supported;
    $out.0.agent_verified = verified;
    $out.0.redemption_blocked = blocked;
    return SKIP;
}
