            $out.0.allocated_xcd = $in.0.crop_proceeds;
        } else {
            $out.0.allocation_code = "ADVANCE_RECOVERY";
            $out.0.allocated_xcd = -$in.0.advance_balance;
        }
    } else if (selectedRule == 5 || selectedRule == 7) {
        if (idx == 0) {
            $out.0.allocation_code = "GROWER";
            $out.0.allocated_xcd = ($in.0.crop_proceeds - $in.0.advance_balance) * 95 / 100;
        } else if (idx == 1) {
            $out.0.allocation_code = "COOPERATIVE";
            $out.0.allocated_xcd = ($in.0.crop_proceeds - $in.0.advance_balance) * 5 / 100;
