    } else if (selectedRule == 6) {
        $out.0.allocation_code = "OFFSET";
        $out.0.allocated_xcd = $in.0.crop_proceeds;
    } else {
        $out.0.allocation_code = "DIRECT";
        $out.0.allocated_xcd = $in.0.crop_proceeds - $in.0.advance_balance;
    }
    return OK;
}
