//#CTL2

function integer filingRule() {
    if ($in.0.filing_class == "WITHDRAWN") return 1;
    if ($in.0.declared_tonnes < 0) return 2;
    if (isnull($in.0.permit_code) || $in.0.permit_code == "") return 3;
    if ($in.0.surveyed_tonnes > $in.0.declared_tonnes) return 4;
    if ($in.0.filing_class == "EXEMPT") return 5;
    // Equivalent to sum >= 200 without overflowing a long sum.
    if ($in.0.declared_tonnes >= 200 - $in.0.surveyed_tonnes && $in.0.audit_selected) return 6;
    if ($in.0.filing_class == "ANNUAL") return 7;
    return 8;
}

function integer count() {
    integer rule = filingRule();
    if (rule == 1 || rule == 5) return 0;
    if (rule == 3 || rule == 4 || rule == 7) return 2;
    if (rule == 6) return 3;
    return 1;
}

function integer transform(integer idx) {
    integer rule = filingRule();
    $out.0.declaration_ref = $in.0.filing_number;
    if (rule == 2) {
        $out.0.ledger_category = "DATA_ERROR";
        $out.0.tonnage_value = -$in.0.declared_tonnes;
    } else if (rule == 3) {
        if (idx == 0) {
            $out.0.ledger_category = "PERMIT_REVIEW";
            $out.0.tonnage_value = $in.0.declared_tonnes;
        } else {
            $out.0.ledger_category = "COMPLIANCE_ALERT";
            $out.0.tonnage_value = 0;
