function integer transform() {
    string card = "";
    if (!isnull($in.0.card_reference)) card = trim($in.0.card_reference);
    string classification;
    if (card == "") classification = "MISSING";
    else if (matches(card, "EL[0-9]{8}")) classification = "VALID";
    else classification = "INVALID";

    string airport = "";
    if (!isnull($in.0.base_airport)) airport = upperCase(trim($in.0.base_airport));
    boolean supported = airport == "WAW" || airport == "KRK" || airport == "OTP" || airport == "SOF";
    boolean verified = false;
    if (!isnull($in.0.service_agent)) verified = matches($in.0.service_agent, "LOY[0-9]{4}");
    boolean blocked = false;
    if (!isnull($in.0.account_frozen)) blocked = $in.0.account_frozen;

    long accrued = $in.0.accrued_miles;
    long requested = $in.0.requested_miles;
    integer issues = 0;
    if (classification != "VALID") issues++;
    if (isnull(accrued)) issues++;
    else if (accrued < 0) issues++;
    if (isnull(requested)) issues++;
    else if (requested <= 0) issues++;
    if (!isnull(accrued) && !isnull(requested)) {
