    else if (accrued < 0) balanceTier = "INVALID";
    else if (accrued >= 100000) balanceTier = "PREMIUM";
    else balanceTier = "REGULAR";

    string requestTier;
    if (isnull(requested)) requestTier = "UNKNOWN";
    else if (requested <= 0) requestTier = "INVALID";
    else if (requested >= 25000) requestTier = "LARGE";
    else requestTier = "SMALL";

    string lane = "REVIEW";
    if (issues == 0) {
        // Here 0 < requested <= accrued. This exact half comparison
        // avoids both fractional truncation and long multiplication overflow.
        if (requested <= accrued - requested) lane = "INSTANT";
        else lane = "APPROVAL";
    }

    $out.0.member_key = $in.0.member_key;
    $out.0.card_classification = classification;
    $out.0.canonical_card = upperCase(card);
